'use strict';
// Real, isolated Nodal BallGrid control function from shipped P7 (not rewritten logic).
// Asserts that Stage 00's installation sound gate and grid-crossing control are sane.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.resolve(process.argv[2]||'.');
const src=fs.readFileSync(path.join(root,'src/nodal/13_installation_ball_grid.js'),'utf8');
const rows=[{id:'g-0',freq:200,manualMuted:false,modeMuted:false}];
const ctx={
  myzelGClamp:x=>Math.max(0,Math.min(1,Number.isFinite(x)?x:0)),
  __xenGridMuted:()=>false,pEe:()=>rows,gj:()=>({min:100,max:300}),tc:100,
  P:{},Set,Map,Object,Math,Number
};
vm.createContext(ctx);
vm.runInContext(src+'\nglobalThis.__testGrid=__NodalBallGrid;',ctx,{timeout:2500});
const api=ctx.__testGrid;
const params={gridTuning:'12edo'};
api.bind({paramsRef:{current:params},modeRef:{current:'installation'},mixRef:{current:{ballToneMode:'grid'}}});
const mix={ballToneMode:'grid',rootLevel:.62,ballToneLevel:1};
const at=y=>({cursorNormalizedY:y});
const s={};
assert.equal(api.control(at(.4),mix,s,1).gate,0,'Cold initialization must not replay a crossing');
const hit=api.control(at(.6),mix,s,1.015);
assert.equal(hit.hz,200,'Line crossing must select the correct precompiled frequency');
assert(hit.gate>0,'Fresh line crossing must produce audible gate');
const quiet=api.control(at(.61),{...mix,ballToneLevel:0},s,1.020);
assert.equal(quiet.gate,0,'Ball-tone mute must silence the grid gate');
assert.equal(quiet.hz,hit.hz,'Mute must not erase chosen pitch');
const delayed=api.control(at(.2),mix,s,2.0);
assert.equal(delayed.gate,0,'A stalled frame must not replay accumulated line events');
console.log('PASS installation Ball Grid crossing, mute, pitch continuity and no late catch-up');
// Separate audio-domain checks without mutating DSP: ensure ball tone gain reaches
// both fallback voices and actual native DSP, while resident voices stay independent.
const fallback=fs.readFileSync(path.join(root,'src/audio/08_myzel_g_live.js'),'utf8');
const dsp=fs.readFileSync(path.join(root,'src/audio/09_myzel_g_dsp.js'),'utf8');
assert.match(fallback,/rootLevel\*\.05\*ballTone\.gate\*ballToneLevel/,'Native fallback ball-tone gain missing');
assert.match(fallback,/ballLevel\*\(\.006\+g\.gestureEnergy\*\.08\)\*ballToneLevel/,'Native fallback ball motion gain missing');
assert.match(dsp,/gains\[0\]=t\.rootLevel\*\.21\*t\.ballToneGate\*t\.ballToneLevel/,'DSP root/ball gain missing');
assert.match(dsp,/gains\[1\]=t\.ballLevel\*.*\*t\.ballToneLevel/,'DSP ball reaction gain missing');
assert.match(dsp,/gains\[2\]=t\.nodeLevel\*t\.presence/,'Resident voice must remain independent of ball-tone mute');
console.log('PASS independent resident-gain boundary, native/Worklet ball-tone muting present');

'use strict';
// Independent, read-only witness: replay every declared source span in memory
// from the user's original Codex basis and compare to the patched checkout.
// Unlike hash-whitelisting, this fails on any additional or altered byte.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const patched=path.resolve(process.argv[2]||'.');
const original=process.argv[3]&&path.resolve(process.argv[3]);
const patchDir=process.argv[4]&&path.resolve(process.argv[4]);
assert(original&&patchDir,'Usage: node tests/p7_2_patch_ancestry.cjs <patched-root> <original-root> <handoff-patches>');
const sha=v=>crypto.createHash('sha256').update(v).digest('hex');
const read=(root,file)=>fs.readFileSync(path.join(root,file),'utf8');
const stages=fs.readdirSync(patchDir).filter(x=>/^0[0-8]_.*\.xpatch\.json$/.test(x)).sort();
assert.equal(stages.length,9,'Exactly nine functional stages must be represented');
const simulated=new Map();let edits=0,files=0;
for(const filename of stages){
 const patch=JSON.parse(fs.readFileSync(path.join(patchDir,filename)));
 for(const f of patch.files){
  const previous=simulated.has(f.path)?simulated.get(f.path):f.new_file?'':read(original,f.path);
  assert.equal(sha(previous),f.before_sha256||sha(''),`Unexpected predecessor of ${filename}: ${f.path}`);
  // xpatch offsets were generated by Python and index Unicode code points,
  // NOT JavaScript UTF-16 units (astral emoji must remain position-safe).
  let points=Array.from(previous);
  for(const edit of [...f.edits].reverse()){
   assert(edit.at>=0&&edit.at+edit.delete<=points.length,'Invalid patch span');
   points.splice(edit.at,edit.delete,...Array.from(edit.insert));
   edits++;
  }
  const result=points.join('');
  assert.equal(sha(result),f.after_sha256,`Unexpected output of ${filename}: ${f.path}`);
  simulated.set(f.path,result);files++;
 }
}
for(const [file,result] of simulated){
 assert.equal(read(patched,file),result,`Unauthorized source difference: ${file}`);
}
const manifestOld=JSON.parse(read(original,'source-manifest.json'));
const manifestNew=JSON.parse(read(patched,'source-manifest.json'));
assert.deepEqual(manifestNew.files.slice(1),manifestOld.files,'Existing source order must not change');
assert.equal(manifestNew.files[0],'src/handoff/00_chat_feature_addons.js','Expected explicit one-file addition');
assert.deepEqual(manifestNew.styles,manifestOld.styles,'Style order must remain unchanged');
console.log(`PASS provenance from actual Codex baseline through 00-08: ${files} file applications, ${edits} exact edits, ${simulated.size} distinct modules`);
console.log('PASS no unreviewed source-span drift in declared modules or assembly order');

'use strict';
// Read-only fresh-index gate. Uses repository TypeScript when installed, with
// global TypeScript only as an explicit fallback for the isolated QA environment.
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),cp=require('node:child_process'),assert=require('node:assert/strict');
const root=path.resolve(process.argv[2]||'.');
const tempfile=fs.mkdtempSync(path.join(os.tmpdir(),'p72-index-'));
try{
 fs.mkdirSync(path.join(tempfile,'tools'));
 fs.copyFileSync(path.join(root,'tools/source_index.cjs'),path.join(tempfile,'tools/source_index.cjs'));
 fs.copyFileSync(path.join(root,'source-manifest.json'),path.join(tempfile,'source-manifest.json'));
 fs.symlinkSync(path.join(root,'src'),path.join(tempfile,'src'),'dir');
 const local=path.join(root,'node_modules');
 if(fs.existsSync(local))fs.symlinkSync(local,path.join(tempfile,'node_modules'),'dir');
 const globalModules=cp.execFileSync('npm',['root','-g'],{encoding:'utf8'}).trim();
 const exec=cp.spawnSync(process.execPath,[path.join(tempfile,'tools/source_index.cjs')],{
   cwd:tempfile,encoding:'utf8',timeout:60000,env:{...process.env,NODE_PATH:[local,globalModules,process.env.NODE_PATH||''].join(path.delimiter)}
 });
 assert.equal(exec.status,0,`Index generation failed: ${exec.stderr||exec.stdout}`);
 const expected=fs.readFileSync(path.join(tempfile,'source-index.json'),'utf8');
 const current=fs.readFileSync(path.join(root,'source-index.json'),'utf8');
 assert.equal(current,expected,'source-index.json is stale: regenerate with npm run map:sources');
 const index=JSON.parse(current);assert(index.declarations.some(x=>x.file==='src/handoff/00_chat_feature_addons.js'),'New tuning/keyboard addon missing in index');
 console.log(`PASS fresh source-index: ${index.declarations.length} declarations / ${index.dependencies.length} file dependencies`);
}finally{fs.rmSync(tempfile,{recursive:true,force:true})}
